 *  1) قاموس مدمج أوفلاين (جلدية + طب عام): بيدوّر بالإنجليزي في النص الأصلي وبالعربي في الترجمة.
 *  2) مصطلح طبي مش في القاموس (لاحقة زي -itis/-osis/-oma/-mycin…) ← ملخص ويكيبيديا + ترجمة جوجل (محتاج نت، بيتأكد إن الصفحة طبية).
 * الشرح تعريفي عام، مش تشخيص ولا نصيحة علاجية.
 */
object TermNotes {
    class Entry(val keys: List<String>, val ar: String, val note: String) {
        val res: List<Regex> = keys.filter { !isAr(it) }.map { Regex("(?<![a-z])" + Regex.escape(it.lowercase()) + "(?:s|es)?(?![a-z])") }
        val arKeys: List<String> = keys.filter { isAr(it) }.map { norm(it) }
    }
    fun enabled(): Boolean = Cfg.str("term_notes", "on") != "off"
    private fun isAr(s: String): Boolean = s.isNotEmpty() && s[0].code in 0x0600..0x06FF
    private fun norm(s: String): String = s.replace(Regex("[\\u064B-\\u0652\\u0640]"), "").replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا').replace('ى', 'ي').replace('ة', 'ه')

    private fun e(keys: String, ar: String, note: String) = Entry(keys.split("|").map { it.trim() }.filter { it.isNotEmpty() }, ar, note)

