    /** المصطلحات الموجودة في النص (الأصل + الترجمة) */
    fun match(text: String): List<Entry> {
        val low = text.lowercase(); val ar = norm(text)
        val out = ArrayList<Entry>()
        for (en in entries) {
            val hit = en.res.any { it.containsMatchIn(low) } || en.arKeys.any { it.length >= 4 && ar.contains(it) }
            if (hit) out.add(en)
        }
        if (out.size > 1) out.removeAll { it.ar == "القوباء" }   // الاسم العام مايتكررش لو في مصطلح أدق
        return out
    }

    /** مصطلح طبي إنجليزي مش في القاموس (حسب اللاحقة) */
    private val medRe = Regex("\\b[A-Za-z]{6,}(?:itis|osis|oma|pathy|emia|ectomy|plasty|mycin|cillin|azole|olol|pril|sartan|statin)\\b")
    fun candidates(text: String): List<String> = medRe.findAll(text).map { it.value }.distinct().filter { w -> entries.none { en -> en.res.any { it.containsMatchIn(w.lowercase()) } } }.take(3).toList()

    private val medDesc = Regex("(?i)medic|disease|disorder|drug|condition|infection|syndrome|cancer|tumou?r|skin|symptom|antibiotic|hormone|surgical|procedure|inflammation|therapy|virus|bacteri|fung")
    private val wikiCache = ConcurrentHashMap<String, Pair<String, String>>()   // مفتاح → (عنوان، جملة)؛ فاضي = مفيش

    /** ملخص ويكيبيديا (إنجليزي) لو الصفحة طبية: (العنوان، أول جملة). null = مفيش/مش طبية/النت واقع */
    fun wiki(term: String): Pair<String, String>? {
        val k = term.lowercase()
        wikiCache[k]?.let { return if (it.first.isEmpty()) null else it }
        var res: Pair<String, String>? = null
        try {
            val c = URL("https://en.wikipedia.org/api/rest_v1/page/summary/" + URLEncoder.encode(term, "UTF-8")).openConnection() as HttpURLConnection
            try {
                c.connectTimeout = 5000; c.readTimeout = 6000
                c.setRequestProperty("User-Agent", "Subtitler/4.08 (Android)")
                if (c.responseCode == 200) {
                    val j = JSONObject(c.inputStream.use { String(it.readBytes(), Charsets.UTF_8) })
                    val desc = j.optString("description", "")
                    val ext = j.optString("extract", "").replace(Regex("\\s*\\([^)]*\\)"), "").trim()
                    if (j.optString("type") == "standard" && medDesc.containsMatchIn(desc) && ext.length > 20) {
                        val first = ext.split(Regex("(?<=[.!?])\\s+")).first().take(220)
                        res = Pair(j.optString("title", term), first)
                    }
                    wikiCache[k] = res ?: Pair("", "")
                }
            } finally { try { c.disconnect() } catch (_: Throwable) {} }
        } catch (_: Exception) {}
        return res
    }
}
